code='''def transform(grid):
    # Extend every same-color diagonal run of at least two cells to the edge,
    # stopping at any existing non-background cell.
    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seeds = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    seeds.append((r, c, dr, dc, color))
    for r, c, dr, dc, color in seeds:
        # Trace the maximal run that contains this adjacent pair, then extend
        # out from both ends along its diagonal.
        sr, sc = r, c
        while 0 <= sr-dr < h and 0 <= sc-dc < w and grid[sr-dr][sc-dc] == color:
            sr, sc = sr-dr, sc-dc
        er, ec = r+dr, c+dc
        while 0 <= er+dr < h and 0 <= ec+dc < w and grid[er+dr][ec+dc] == color:
            er, ec = er+dr, ec+dc
        for rr, cc, ar, ac in ((sr, sc, -dr, -dc), (er, ec, dr, dc)):
            rr += ar; cc += ac
            while 0 <= rr < h and 0 <= cc < w:
                if out[rr][cc] == color:
                    rr += ar; cc += ac
                    continue
                if out[rr][cc] != background:
                    break
                out[rr][cc] = color
                rr += ar; cc += ac
    return out
'''
